defmodule Prism.Generator.HeaderTest do
  use ExUnit.Case, async: true

  alias Prism.Generator.Header

  @moduletag :tmp_dir

  test "the line names the design's file, in the comment syntax of the file" do
    assert Header.line("tailwind.preset.js", "design/lib/a.ex") ==
             "// Generated by prism (mix prism.gen). Do not edit: change design/lib/a.ex and regenerate."

    assert Header.line("css/base.css", "design/lib/a.ex") ==
             "/* Generated by prism (mix prism.gen). Do not edit: change design/lib/a.ex and regenerate. */"
  end

  test "text that can't be a comment, or a file type without a comment syntax, fails" do
    assert_raise ArgumentError, ~r/can't be written in a comment/, fn ->
      Header.line("css/base.css", "lib/*/a.ex")
    end

    assert_raise ArgumentError, ~r/no comment syntax for .txt files/, fn ->
      Header.line("notes.txt", "lib/a.ex")
    end
  end

  test "generated? recognises the line", %{tmp_dir: dir} do
    generated = Path.join(dir, "a.css")
    File.write!(generated, Header.line("a.css", "lib/a.ex") <> "\nbody\n")
    assert Header.generated?(generated)

    hand_written = Path.join(dir, "b.css")
    File.write!(hand_written, "/* hand-written */\n")
    refute Header.generated?(hand_written)
  end
end
